-- Kiểm tra sau import
SELECT COUNT(*) AS so_dong_01_07_2026
FROM lich_su_tieu_thu
WHERE ngay_ban BETWEEN DATE '2026-02-01' AND DATE '2026-07-31';

SELECT ma_san_pham, COUNT(*) AS so_dong, SUM(so_luong_ban) AS tong_so_luong
FROM lich_su_tieu_thu
WHERE ngay_ban BETWEEN DATE '2026-01-01' AND DATE '2026-07-31'
GROUP BY ma_san_pham
ORDER BY ma_san_pham;
